describe('Search Input Focus on Slash Key', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should focus search input when "/" key is pressed', () => {
    cy.get('input[type="search"], input[placeholder*="search" i], [data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').should('exist');
    cy.get('@searchInput').should('not.have.focus');

    cy.get('body').type('/');

    cy.get('@searchInput').should('have.focus');
  });

  it('should not focus search input when "/" is typed in an input field', () => {
    cy.get('input[type="search"], input[placeholder*="search" i], [data-testid="search-input"]').as('searchInput');
    cy.get('input[type="text"]').first().as('otherInput');

    cy.get('@otherInput').focus();
    cy.get('@otherInput').type('/');

    cy.get('@searchInput').should('not.have.focus');
    cy.get('@otherInput').should('have.focus');
  });

  it('should focus search input when "/" is pressed after clicking elsewhere', () => {
    cy.get('input[type="search"], input[placeholder*="search" i], [data-testid="search-input"]').as('searchInput');

    cy.get('body').click();
    cy.get('@searchInput').should('not.have.focus');

    cy.get('body').type('/');

    cy.get('@searchInput').should('have.focus');
  });

  it('should clear existing text and focus when "/" is pressed on focused search input', () => {
    cy.get('input[type="search"], input[placeholder*="search" i], [data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').focus().type('test');
    cy.get('@searchInput').should('have.value', 'test');

    cy.get('body').type('/');

    cy.get('@searchInput').should('have.focus');
  });
});
